local function translate(key, ...)
    local locale = tostring(Config and Config.Locale or 'de'):lower()
    local lang = Locales[locale] or Locales.de or {}
    local text = lang[key] or (Locales.de and Locales.de[key]) or key
    local args = { ... }
    if #args > 0 then
        local unpackFn = table.unpack or unpack
        local ok, formatted = pcall(string.format, text, unpackFn(args))
        if ok then return formatted end
    end
    return text
end

UG = UG or {}
UG.Translate = translate
UG.L = translate
_G._L = translate
